                + "was ever built, and Adventurers' Guild hunters camped nearby swear "
                + "the ring moves half a pace every full moon. One hunter, well into "
                + "her cups from the Angel's Share, waves you toward the center and "
                + "says the ring pays generously for company — and asks nothing at "
                + "all of anyone who just keeps walking.",
            ["WOLF_RING_ABOVE_WINDRISE.pages.INITIAL.options.GROUP.title"] =
                "Group",
            ["WOLF_RING_ABOVE_WINDRISE.pages.INITIAL.options.GROUP.description"] =
                "You empty your purse into the grass and let the ring do as it "
                + "likes. Lose ALL of your Gold (Mora). Transform 2 cards.",
            ["WOLF_RING_ABOVE_WINDRISE.pages.INITIAL.options.LONER.title"] =
                "Loner",
            ["WOLF_RING_ABOVE_WINDRISE.pages.INITIAL.options.LONER.description"] =
                "You walk on toward Windrise and let the quiet do its own work. "
                + "Gain 5 Max HP.",
            ["WOLF_RING_ABOVE_WINDRISE.pages.LONER.description"] =
                "You walk on toward Windrise and let the quiet do its own work. "
                + "Gain 5 Max HP.",
            ["WOLF_RING_ABOVE_WINDRISE.pages.GROUP.description"] =
                "You empty your purse into the grass and let the ring do as it "
                + "likes. Lose ALL of your Gold (Mora). Transform 2 cards.",
            // SpringvaleCheeseCellar (Mondstadt / RoomFullOfCheese)
            ["SPRINGVALE_CHEESE_CELLAR.title"] =
                "The Springvale Cheese Cellar",
            ["SPRINGVALE_CHEESE_CELLAR.pages.INITIAL.description"] =
                "A collapsed stair below Springvale opens onto a dairy cellar the "
                + "Guild's commission board never got around to delisting. Wheels of "
                + "Mondstadt cheese sit rack on rack, gold-rinded and humming with "
                + "age, and the slip in your hand says only: inventory it. Behind the "
                + "furthest rack, something older than the racks is sweating brine.",
            ["SPRINGVALE_CHEESE_CELLAR.pages.INITIAL.options.GORGE.title"] =
                "Taste the Racks",
            ["SPRINGVALE_CHEESE_CELLAR.pages.INITIAL.options.GORGE.description"] =
                "Choose 2 of 8 random Common cards to add to your Deck. The eight "
                + "wheels offered are never duplicates.",
            ["SPRINGVALE_CHEESE_CELLAR.pages.INITIAL.options.SEARCH.title"] =
                "Haul Out the Back Wall",
            ["SPRINGVALE_CHEESE_CELLAR.pages.INITIAL.options.SEARCH.description"] =
                "Lose 14 HP to strained shoulders and spore-thick air. Obtain The "
                + "Anointed Wheel (The Chosen Cheese): at the end of combat, gain 1 "
                + "Max HP.",
            ["SPRINGVALE_CHEESE_CELLAR.pages.GORGE.selectionScreenPrompt"] =
                "Taste the Racks",
            ["SPRINGVALE_CHEESE_CELLAR.pages.GORGE.description"] =
                "Choose 2 of 8 random Common cards to add to your Deck. The eight "
                + "wheels offered are never duplicates.",
            ["SPRINGVALE_CHEESE_CELLAR.pages.SEARCH.description"] =
