            ["CONTRACT_RECITING_GROWTH.pages.INITIAL.options.RIP.description"] =
                "Lose 5 HP. Gain a Colorless 2 card reward.",
            ["CONTRACT_RECITING_GROWTH.pages.RIP.description"] =
