            ["STEEPER_AT_HEYU.pages.INITIAL.options.TEA_OF_DISCOURTESY.title"] =
                "Tea of Discourtesy",
            ["STEEPER_AT_HEYU.pages.INITIAL.options.TEA_OF_DISCOURTESY.description"] =
